/**
 * forge-get-acrobat-studio-today — variant DISPATCHER (generated by variant-dispatcher.js).
 *
 * The authored DA content wraps multiple visually-distinct sections in generic
 * `forge-get-acrobat-studio-today` blocks with flat content. Rather than re-author the document,
 * this block SNIFFS each instance's content signature, tags it
 * `forge-get-acrobat-studio-today--<variant>`, and hands it to the matching lazy-loaded variant
 * decorator, which rebuilds the flat rows into the rich layout in place.
 *
 * Variant decorators + styles live under ./variants/* so each is developed and
 * fault-isolated independently: a broken variant fails ONLY its own section. If
 * no variant matches (block used generically elsewhere), we fall back to the
 * original generic decoration so the catalog block stays backward-compatible.
 */
// CANONICAL DEPTH: from libs/c2/blocks/<name>/ to libs/c2/utils/decorate.js is
// THREE hops up (blocks → c2 → utils). The 3-hop '../../../' form is CORRECT.
import { decorateBlockText, decorateViewportContent } from '../../../utils/decorate.js';

const BLOCK = 'forge-get-acrobat-studio-today';

// Per-page values the variant rebuilds read as DATA (Phase 5.1). Driven from the
// extraction at generate time — NOT a baked page constant. Empty {} when the
// extraction carried none, in which case rebuilds use their generic defaults.
const META = {};

// Lazy per-variant loaders: a broken/in-progress variant module can only fail
// its own section, never cascade to the others.
const LOADERS = {
  "lockup": () => import('./variants/lockup.js'),
};

const APP_GLYPH = /^[A-Za-z]{2,4}$/;

/** Identify which variant (if any) this forge-get-acrobat-studio-today instance is. */
function detectVariant(el) {
  const section = el.closest('.section');
  const sectionStyle = section ? section.className : '';
  if (/merch/i.test(sectionStyle) && LOADERS.merch) return 'merch';

  const rows = [...el.querySelectorAll(':scope > div')];
  if (!rows.length) return null;
  const contentCells = rows.map((r) => r.querySelector(':scope > div'));

  if (contentCells.some((c) => c && c.querySelectorAll(':scope > p').length > 8)) {
    return LOADERS.roller ? 'roller' : null;
  }

  if (rows.length === 1) {
    const cell = contentCells[0];
    if (!cell) return null;
    if (cell.querySelector('a') && LOADERS.lockup) return 'lockup';
    const paras = cell.querySelectorAll(':scope > p').length;
    if (paras >= 4 && LOADERS.accordion) return 'accordion';
    return LOADERS.lockup ? 'lockup' : null;
  }

  const lead = (cell) => cell && cell.querySelector(':scope > p, :scope > h2, :scope > h3, :scope > h4');
  const leadsWithGlyph = contentCells.every((c) => {
    const first = lead(c);
    return first && first.tagName === 'P' && APP_GLYPH.test(first.textContent.trim());
  });
  if (leadsWithGlyph && LOADERS.bento) return 'bento';

  const leadsWithHeading = contentCells.every((c) => {
    const first = lead(c);
    return first && /^H[2-4]$/.test(first.tagName);
  });
  if (leadsWithHeading && LOADERS['bento-tiles']) return 'bento-tiles';

  return null;
}

/* ---- generic decorate (backward-compatible fallback) ----
 * No variant matched: keep the authored DOM and run Milo's own text decorator so
 * the section is still a real, reusable Milo block rather than an inert shim. */
function genericDecorate(scope) {
  const inner = scope.querySelector(':scope > div > div') || scope;
  if (typeof decorateBlockText === 'function') decorateBlockText(inner);
}

// Disambiguates daa-lh across N same-name instances on one page (a 1-based
// index suffix). Borrows the "index disambiguates repeats" idea behind
// Milo's own decorateSectionAnalytics (a "b<idx>|" prefix for blocks that
// don't pre-set daa-lh) but is not identical to it — see daa-tagging.js.
function forgeInstanceSuffix(el, blockName) {
  const instances = [...document.querySelectorAll(`.${blockName}`)];
  const idx = instances.indexOf(el);
  return instances.length > 1 && idx >= 0 ? `-${idx + 1}` : '';
}

// Deterministic analytics tagging (forge-owned; NOT dependent on AI-author
// compliance — see block-author.js C7). Milo's own per-link auto-labeling
// (decorateDefaultLinkAnalytics, invoked from decorateSectionAnalytics) only
// runs on a block with NO daa-lh of its own; this block sets its own daa-lh
// above, so it opted OUT of that free labeling — this is the replacement.
// Idempotent: skips any link/button/image that already carries daa-ll/daa-im
// (an AI-authored node that already complied with C7) so it never double-tags.
function forgeTagAnalytics(scope, label) {
  if (!scope) return;
  const slugify = (text) => String(text || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40);
  let linkIdx = 0;
  scope.querySelectorAll('a, button').forEach((node) => {
    if (node.hasAttribute('daa-ll')) return;
    linkIdx += 1;
    const text = node.textContent || node.getAttribute('aria-label') || node.getAttribute('title') || '';
    node.setAttribute('daa-ll', `${label}|${slugify(text) || `link-${linkIdx}`}`);
  });
  let imgIdx = 0;
  scope.querySelectorAll('img').forEach((img) => {
    if (img.hasAttribute('daa-im')) return;
    imgIdx += 1;
    img.setAttribute('daa-im', `${label}|${slugify(img.getAttribute('alt')) || `image-${imgIdx}`}`);
  });
}

export default async function init(el) {
  if (!el) return;
  // Section-level analytics handle, disambiguated across N same-name
  // instances on the page (see forgeInstanceSuffix above).
  const suffix = forgeInstanceSuffix(el, BLOCK);
  let daaLh = `${BLOCK}${suffix}`;
  el.setAttribute('daa-lh', daaLh);
  // Surface per-page META to the rebuilds as data-* (e.g. the roller's active app),
  // so a variant module reads page data without importing a page constant.
  if (META.activeApp && el.dataset && !el.dataset.activeApp) el.dataset.activeApp = META.activeApp;
  const variant = detectVariant(el);
  if (!variant || !LOADERS[variant]) {
    if (typeof decorateViewportContent === 'function') {
      decorateViewportContent(el, genericDecorate);
    } else {
      genericDecorate(el);
    }
    // Deterministic analytics floor — tags any link/button/image the generic
    // fallback left untagged (independent of AI-author compliance).
    forgeTagAnalytics(el, daaLh);
    return;
  }
  el.classList.add(`${BLOCK}--${variant}`);
  daaLh = `${BLOCK}-${variant}${suffix}`;
  el.setAttribute('daa-lh', daaLh);
  try {
    const mod = await LOADERS[variant]();
    await mod.default(el, { decorateBlockText, decorateViewportContent });
    el.dataset.forgeVariant = variant;
  } catch (e) {
    // Never let a variant decorator blank the section — leave authored DOM.
    window.lana?.log?.(`${BLOCK} ${variant} failed: ${e.message}`);
  }
  // Deterministic analytics floor — tags any link/button/image the variant
  // rebuild created without its own daa-ll/daa-im (independent of the variant
  // module's own compliance; runs even if the rebuild above threw, so
  // whatever DOM is left — rebuilt or untouched authored — still gets tagged).
  forgeTagAnalytics(el, daaLh);
}
